import numpy as np
from scipy import stats

MAX_DRIVERS = 5

def design(feats):
    # Identify strong candidates based on mean difference and t-statistic
    strong_candidates = []
    for i, fid in enumerate(feats.ids):
        if abs(feats.x[:, i].mean() * feats.y.mean()) > 0.1 and abs(stats.ttest_ind(feats.x[feats.y==1, i], feats.x[feats.y==0, i])[0]) > 2:
            strong_candidates.append(fid)

    # Find correlated pairs (|r| >= 0.6)
    corr_pairs = []
    for i, a in enumerate(feats.ids):
        for j, b in enumerate(feats.ids):
            if i < j:
                corr = np.corrcoef(feats.x[:, i], feats.x[:, j])[0, 1]
                if abs(corr) >= 0.6:
                    corr_pairs.append((a, b))

    # Remove duplicates and near-duplicates
    unique_pairs = set()
    for a, b in corr_pairs:
        if (a, b) not in unique_pairs and (b, a) not in unique_pairs:
            unique_pairs.add((a, b))

    # Build clusters
    all_features = list(feats.ids)
    clusters = []
    used = set()

    for a, b in unique_pairs:
        if a not in used and b not in used:
            clusters.append([a, b])
            used.add(a)
            used.add(b)

    # Add unclustered features to their own clusters
    for fid in all_features:
        if fid not in used:
            clusters.append([fid])

    # Select representative from each cluster (strongest candidate)
    representatives = []
    for cluster in clusters:
        if len(cluster) == 1:
            representatives.append(cluster[0])
        else:
            # Choose the one with highest absolute t-statistic
            best_fid = max(cluster, key=lambda f: abs(stats.ttest_ind(feats.x[feats.y==1, feats.column(f)], feats.x[feats.y==0, feats.column(f)])[0]))
            representatives.append(best_fid)

    # Return top candidates as drivers (limit to 4 as per error message)
    drivers = tuple(representatives[:4])

    # All features that could be useful
    columns = tuple(feats.ids)

    # No products needed
    products = ()

    # Loadings based on t-statistics
    loadings = {}
    for i, fid in enumerate(feats.ids):
        t_stat = stats.ttest_ind(feats.x[feats.y==1, i], feats.x[feats.y==0, i])[0]
        loadings[fid] = t_stat

    return Design(drivers=drivers, columns=columns, products=products, loadings=loadings)
